    {
        // Replace with any non-HTTP operation, e.g. file IO, DB call, etc.
        Console.WriteLine("Performing non-HTTP operation...");
        await MyNonHttpOperationAsync();
    });
}
catch (BrokenCircuitException)
{
    Console.WriteLine("Circuit is open! Operation is not permitted right now.");
}
```

Replace `MyNonHttpOperationAsync` with your actual async operation; it can throw exceptions that the circuit breaker will track.

---

